import prisma from './db';
import { sendPushToUser, getLeaderIdsForWorker, getManagerIdsForWorker } from './push';

export async function getTotalPoints(userId: string): Promise<number> {
  const result = await prisma.userPointsTransaction.aggregate({
    where: { userId },
    _sum: { points: true }
  });
  return result?._sum?.points ?? 0;
}

// Pobierz kolor kasku na podstawie helmetLevel użytkownika
export function getHelmetColorFromLevel(helmetLevel: string): { name: string; helmetColor: string; borderColor: string } {
  const levels: Record<string, { name: string; helmetColor: string; borderColor: string }> = {
    green: { name: 'Nowicjusz', helmetColor: '#22C55E', borderColor: '#16A34A' },
    blue: { name: 'Doświadczony', helmetColor: '#3B82F6', borderColor: '#2563EB' },
    orange: { name: 'Specjalista', helmetColor: '#F97316', borderColor: '#EA580C' },
    red: { name: 'Brygadzista', helmetColor: '#EF4444', borderColor: '#DC2626' }
  };
  return levels[helmetLevel] ?? levels.green;
}

// Pobierz informacje o tytule użytkownika (dla kompatybilności)
export async function getUserTitle(totalPoints: number, helmetLevel?: string) {
  // Jeśli podano helmetLevel, użyj go
  if (helmetLevel) {
    return getHelmetColorFromLevel(helmetLevel);
  }

  // Fallback do starego systemu bazującego na punktach (dla kompatybilności)
  const title = await prisma.title.findFirst({
    where: {
      minPoints: { lte: totalPoints },
      OR: [
        { maxPoints: { gte: totalPoints } },
        { maxPoints: null }
      ]
    },
    orderBy: { orderIndex: 'desc' }
  });

  return title ?? {
    name: 'Nowicjusz',
    helmetColor: '#22C55E',
    borderColor: '#16A34A',
    minPoints: 0,
    maxPoints: 99
  };
}

export async function getConfigValue(key: string, defaultValue: string = '0'): Promise<string> {
  const config = await prisma.systemConfig.findUnique({ where: { key } });
  return config?.value ?? defaultValue;
}

// Pobierz maksymalne punkty dla konfiguracji (górna granica)
export async function getUpperLimitPoints(): Promise<number> {
  const config = await prisma.systemConfig.findUnique({ where: { key: 'upper_limit_points' } });
  return parseInt(config?.value ?? '100', 10);
}

export async function addPointsTransaction(
  userId: string,
  points: number,
  transactionType: 'daily_login' | 'bhp_quiz' | 'admin_adjustment' | 'news_read' | 'instruction_read' | 'exercise_completion' | 'mission_completed' | 'monthly_quiz' | 'pre_shift' | 'bonus_points' | 'certification_bonus',
  description?: string,
  createdById?: string
) {
  // Dodaj transakcję
  const transaction = await prisma.userPointsTransaction.create({
    data: {
      userId,
      points,
      transactionType: transactionType as 'daily_login' | 'bhp_quiz' | 'admin_adjustment' | 'news_read' | 'instruction_read' | 'exercise_completion' | 'mission_completed' | 'monthly_quiz' | 'pre_shift' | 'bonus_points',
      description,
      createdById
    }
  });

  // Aktualizuj miesięczne punkty użytkownika
  if (points > 0) {
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { monthlyPoints: true, helmetLevel: true, firstName: true, lastName: true, isAtUpperLimit: true }
    });

    if (user) {
      const newMonthlyPoints = (user.monthlyPoints || 0) + points;
      const upperLimit = await getUpperLimitPoints();
      const previouslyBelowLimit = (user.monthlyPoints || 0) < upperLimit;

      // Sprawdź czy użytkownik osiągnął górną granicę
      const isAtUpperLimit = newMonthlyPoints >= upperLimit;
      const justCrossedLimit = previouslyBelowLimit && isAtUpperLimit && !user.isAtUpperLimit;

      await prisma.user.update({
        where: { id: userId },
        data: {
          monthlyPoints: newMonthlyPoints,
          isAtUpperLimit: user.helmetLevel === 'blue' ? isAtUpperLimit : user.isAtUpperLimit
        }
      });

      // Jeśli właśnie przekroczył próg - powiadom brygadzistę i kierownika
      if (justCrossedLimit) {
        const workerName = `${user.firstName} ${user.lastName}`;
        const notificationBody = `${workerName} osiągnął ${upperLimit} punktów miesięcznych! 🎉`;

        // Powiadom brygadzistów
        const leaderIds = await getLeaderIdsForWorker(userId);
        for (const leaderId of leaderIds) {
          await prisma.notification.create({
            data: {
              userId: leaderId,
              type: 'top5_achievement',
              title: 'Pracownik osiągnął próg punktów',
              message: notificationBody,
              relatedId: userId
            }
          });

          await sendPushToUser(leaderId, {
            title: '🏆 Próg punktów osiągnięty',
            body: notificationBody,
            tag: 'points-threshold',
            data: { url: '/dashboard/leader/team' }
          });
        }

        // Powiadom kierowników
        const managerIds = await getManagerIdsForWorker(userId);
        for (const managerId of managerIds) {
          await prisma.notification.create({
            data: {
              userId: managerId,
              type: 'top5_achievement',
              title: 'Pracownik osiągnął próg punktów',
              message: notificationBody,
              relatedId: userId
            }
          });

          await sendPushToUser(managerId, {
            title: '🏆 Próg punktów osiągnięty',
            body: notificationBody,
            tag: 'points-threshold-manager',
            data: { url: '/dashboard/manager' }
          });
        }
      }
    }
  }

  return transaction;
}

