import { NextRequest, NextResponse } from 'next/server';
import prisma from '@/lib/db';
import { verifyToken } from '@/lib/auth';
import { cookies } from 'next/headers';

export const dynamic = 'force-dynamic';

// GET - pobierz użytkowników z informacją o kaskach
export async function GET(request: NextRequest) {
  try {
    const cookieStore = await cookies();
    const token = cookieStore.get('auth_token')?.value;
    if (!token) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const decoded = verifyToken(token);
    if (!decoded || (decoded.role !== 'admin' && decoded.role !== 'manager')) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    // Pobierz pracowników (nie liderów/adminów/kierowników)
    const users = await prisma.user.findMany({
      where: {
        role: { in: ['worker', 'leader'] }
      },
      select: {
        id: true,
        employeeId: true,
        firstName: true,
        lastName: true,
        role: true,
        helmetLevel: true,
        startDate: true,
        isAtUpperLimit: true,
        monthlyPoints: true,
        createdAt: true,
        pointsTransactions: {
          select: { points: true }
        }
      },
      orderBy: { lastName: 'asc' }
    });

    const usersWithStats = users.map(user => {
      const totalPoints = user.pointsTransactions.reduce((sum, t) => sum + t.points, 0);
      const workingDays = user.startDate 
        ? Math.floor((Date.now() - new Date(user.startDate).getTime()) / (1000 * 60 * 60 * 24))
        : Math.floor((Date.now() - new Date(user.createdAt).getTime()) / (1000 * 60 * 60 * 24));

      return {
        id: user.id,
        employeeId: user.employeeId,
        firstName: user.firstName,
        lastName: user.lastName,
        role: user.role,
        helmetLevel: user.helmetLevel,
        startDate: user.startDate,
        isAtUpperLimit: user.isAtUpperLimit,
        monthlyPoints: user.monthlyPoints,
        totalPoints,
        workingDays
      };
    });

    return NextResponse.json(usersWithStats);
  } catch (error) {
    console.error('Error fetching helmet data:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

// PUT - zmień kolor kasku pracownika
export async function PUT(request: NextRequest) {
  try {
    const cookieStore = await cookies();
    const token = cookieStore.get('auth_token')?.value;
    if (!token) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const decoded = verifyToken(token);
    if (!decoded || (decoded.role !== 'admin' && decoded.role !== 'manager')) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const { userId, helmetLevel, startDate } = await request.json();

    if (!userId || !helmetLevel) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }

    // Sprawdź czy użytkownik istnieje
    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    // Dla liderów zawsze czerwony kask
    if (user.role === 'leader' && helmetLevel !== 'red') {
      return NextResponse.json({ error: 'Brygadzista musi mieć czerwony kask' }, { status: 400 });
    }

    // Przy awansie na niebieski - reset isAtUpperLimit
    const updateData: { helmetLevel: 'green' | 'blue' | 'orange' | 'red'; startDate?: Date; isAtUpperLimit?: boolean } = {
      helmetLevel: helmetLevel as 'green' | 'blue' | 'orange' | 'red'
    };

    if (startDate) {
      updateData.startDate = new Date(startDate);
    }

    // Przy zmianie kasku - reset flagi górnej granicy
    if (helmetLevel !== user.helmetLevel) {
      updateData.isAtUpperLimit = false;
    }

    const updatedUser = await prisma.user.update({
      where: { id: userId },
      data: updateData,
      select: {
        id: true,
        firstName: true,
        lastName: true,
        helmetLevel: true,
        startDate: true
      }
    });

    // Wyślij powiadomienie o awansie
    if (helmetLevel !== user.helmetLevel) {
      const helmetNames: Record<string, string> = {
        green: 'Zielony (Nowicjusz)',
        blue: 'Niebieski (Doświadczony)',
        orange: 'Pomarańczowy (Specjalista)',
        red: 'Czerwony (Brygadzista)'
      };

      await prisma.notification.create({
        data: {
          userId,
          type: 'bonus_points',
          title: 'Zmiana poziomu kasku!',
          message: `Twój poziom kasku został zmieniony na: ${helmetNames[helmetLevel]}`,
          senderId: decoded.userId
        }
      });
    }

    return NextResponse.json(updatedUser);
  } catch (error) {
    console.error('Error updating helmet:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

