import webpush from 'web-push';
import { prisma } from './db';

// Configure VAPID
const VAPID_PUBLIC_KEY = process.env.VAPID_PUBLIC_KEY || '';
const VAPID_PRIVATE_KEY = process.env.VAPID_PRIVATE_KEY || '';

if (VAPID_PUBLIC_KEY && VAPID_PRIVATE_KEY) {
  webpush.setVapidDetails(
    'mailto:admin@amsafety.app',
    VAPID_PUBLIC_KEY,
    VAPID_PRIVATE_KEY
  );
}

export interface PushPayload {
  title: string;
  body: string;
  icon?: string;
  badge?: string;
  tag?: string;
  data?: {
    url?: string;
    [key: string]: unknown;
  };
}

/**
 * Send push notification to a specific user
 */
export async function sendPushToUser(userId: string, payload: PushPayload): Promise<void> {
  try {
    const subscriptions = await prisma.pushSubscription.findMany({
      where: { userId }
    });

    if (subscriptions.length === 0) {
      console.log(`No push subscriptions found for user ${userId}`);
      return;
    }

    const notificationPayload = JSON.stringify({
      title: payload.title,
      body: payload.body,
      icon: payload.icon || '/icon-192.png',
      badge: payload.badge || '/icon-192.png',
      tag: payload.tag,
      data: payload.data || {}
    });

    const results = await Promise.allSettled(
      subscriptions.map(async (sub) => {
        try {
          await webpush.sendNotification(
            {
              endpoint: sub.endpoint,
              keys: {
                p256dh: sub.p256dh,
                auth: sub.auth
              }
            },
            notificationPayload
          );
        } catch (error: unknown) {
          // Handle expired/invalid subscriptions
          const webPushError = error as { statusCode?: number };
          if (webPushError.statusCode === 410 || webPushError.statusCode === 404) {
            console.log(`Removing expired subscription: ${sub.endpoint}`);
            await prisma.pushSubscription.delete({
              where: { id: sub.id }
            });
          }
          throw error;
        }
      })
    );

    const successful = results.filter(r => r.status === 'fulfilled').length;
    const failed = results.filter(r => r.status === 'rejected').length;
    console.log(`Push sent to user ${userId}: ${successful} success, ${failed} failed`);
  } catch (error) {
    console.error(`Error sending push to user ${userId}:`, error);
  }
}

/**
 * Send push notification to multiple users (optimized - single DB query)
 */
export async function sendPushToUsers(userIds: string[], payload: PushPayload): Promise<void> {
  if (userIds.length === 0) return;

  try {
    // Single query to get all subscriptions for all users
    const subscriptions = await prisma.pushSubscription.findMany({
      where: { userId: { in: userIds } }
    });

    if (subscriptions.length === 0) {
      console.log(`No push subscriptions found for ${userIds.length} users`);
      return;
    }

    const notificationPayload = JSON.stringify({
      title: payload.title,
      body: payload.body,
      icon: payload.icon || '/icon-192.png',
      badge: payload.badge || '/icon-192.png',
      tag: payload.tag,
      data: payload.data || {}
    });

    // Process in batches of 10 to avoid overwhelming
    const batchSize = 10;
    const expiredSubscriptionIds: string[] = [];
    let successful = 0;
    let failed = 0;

    for (let i = 0; i < subscriptions.length; i += batchSize) {
      const batch = subscriptions.slice(i, i + batchSize);
      const results = await Promise.allSettled(
        batch.map(async (sub) => {
          try {
            await webpush.sendNotification(
              {
                endpoint: sub.endpoint,
                keys: {
                  p256dh: sub.p256dh,
                  auth: sub.auth
                }
              },
              notificationPayload
            );
          } catch (error: unknown) {
            const webPushError = error as { statusCode?: number };
            if (webPushError.statusCode === 410 || webPushError.statusCode === 404) {
              expiredSubscriptionIds.push(sub.id);
            }
            throw error;
          }
        })
      );

      successful += results.filter(r => r.status === 'fulfilled').length;
      failed += results.filter(r => r.status === 'rejected').length;
    }

    // Clean up expired subscriptions in single query
    if (expiredSubscriptionIds.length > 0) {
      await prisma.pushSubscription.deleteMany({
        where: { id: { in: expiredSubscriptionIds } }
      });
      console.log(`Removed ${expiredSubscriptionIds.length} expired subscriptions`);
    }

    console.log(`Push sent to ${userIds.length} users: ${successful} success, ${failed} failed`);
  } catch (error) {
    console.error('Error sending push to users:', error);
  }
}

/**
 * Send push notification to all users with a specific role
 */
export async function sendPushToRole(role: 'worker' | 'leader' | 'manager' | 'admin', payload: PushPayload): Promise<void> {
  try {
    const users = await prisma.user.findMany({
      where: { role },
      select: { id: true }
    });

    const userIds = users.map(u => u.id);
    await sendPushToUsers(userIds, payload);
  } catch (error) {
    console.error(`Error sending push to role ${role}:`, error);
  }
}

/**
 * Send push notification to all users (for news/campaigns)
 */
export async function sendPushToAllUsers(payload: PushPayload): Promise<void> {
  try {
    const users = await prisma.user.findMany({
      where: { role: { in: ['worker', 'leader'] } },
      select: { id: true }
    });

    const userIds = users.map(u => u.id);
    await sendPushToUsers(userIds, payload);
  } catch (error) {
    console.error('Error sending push to all users:', error);
  }
}

/**
 * Send push notification to workers of a specific shift
 */
export async function sendPushToShiftWorkers(shiftId: string, payload: PushPayload): Promise<void> {
  try {
    const shiftMembers = await prisma.shiftMember.findMany({
      where: { shiftId },
      select: { workerId: true }
    });

    const workerIds = shiftMembers.map(m => m.workerId);
    await sendPushToUsers(workerIds, payload);
  } catch (error) {
    console.error(`Error sending push to shift ${shiftId}:`, error);
  }
}

/**
 * Send push notification to leader's team workers
 */
export async function sendPushToTeamWorkers(leaderId: string, payload: PushPayload): Promise<void> {
  try {
    const teamMembers = await prisma.teamMember.findMany({
      where: { leaderId },
      select: { workerId: true }
    });

    const workerIds = teamMembers.map(m => m.workerId);
    await sendPushToUsers(workerIds, payload);
  } catch (error) {
    console.error(`Error sending push to team of leader ${leaderId}:`, error);
  }
}

/**
 * Send push notification to managers assigned to a leader
 */
export async function sendPushToLeaderManagers(leaderId: string, payload: PushPayload): Promise<void> {
  try {
    const managerAssignments = await prisma.managerLeader.findMany({
      where: { leaderId },
      select: { managerId: true }
    });

    const managerIds = managerAssignments.map(m => m.managerId);
    await sendPushToUsers(managerIds, payload);
  } catch (error) {
    console.error(`Error sending push to managers of leader ${leaderId}:`, error);
  }
}

/**
 * Send push notification to all managers
 */
export async function sendPushToAllManagers(payload: PushPayload): Promise<void> {
  await sendPushToRole('manager', payload);
}

/**
 * Send push notification to all leaders
 */
export async function sendPushToAllLeaders(payload: PushPayload): Promise<void> {
  await sendPushToRole('leader', payload);
}

/**
 * Get leader(s) for a worker
 */
export async function getLeaderIdsForWorker(workerId: string): Promise<string[]> {
  const teamMembers = await prisma.teamMember.findMany({
    where: { workerId },
    select: { leaderId: true }
  });
  return teamMembers.map(m => m.leaderId);
}

/**
 * Get manager(s) for a worker (via their leader)
 */
export async function getManagerIdsForWorker(workerId: string): Promise<string[]> {
  const leaderIds = await getLeaderIdsForWorker(workerId);

  if (leaderIds.length === 0) return [];

  const managerAssignments = await prisma.managerLeader.findMany({
    where: { leaderId: { in: leaderIds } },
    select: { managerId: true }
  });

  return [...new Set(managerAssignments.map(m => m.managerId))];
}

export { VAPID_PUBLIC_KEY };

